/**
 * Build the generated `app/js/**` tree when it is absent, so a command that reads it can run on a fresh checkout.
 *
 * `app/js/**` is compiler output plus copied vendor bundles, generated by `build.mjs` and not committed; the test suites import it directly, and `bun run typecheck` resolves its vendored `.d.ts` shims. This module is both a `bun test` preload (see `bunfig.toml`) and the first step of the `typecheck` script, so it runs before either reader touches the tree.
 * It builds only when the entry module is missing: an existing tree is left as-is so the acceptance gate can still compare it against a fresh build and report a stale or hand-edited one.
 */

import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const entry = join(root, "app", "js", "main.js");

if (!existsSync(entry)) {
	const build = spawnSync(process.execPath, [join(root, "build.mjs")], { cwd: root, stdio: "inherit" });
	if (build.status !== 0) {
		throw new Error(`app/js/ is missing and a fresh build failed (exit ${build.status})`);
	}
}
